-- Volcando estructura para procedimiento certificate_manager.sp_create_general_settings
DROP PROCEDURE IF EXISTS `sp_create_general_settings`;
DELIMITER //
CREATE PROCEDURE `sp_create_general_settings`(
	IN `PCompanyId` BIGINT
)
BEGIN
	SELECT b.id, a.id, a.`value`, a.`active`
	FROM general_settings AS a, companies AS b
	WHERE NOT EXISTS (
		SELECT 1 FROM general_setting_companies AS c WHERE c.setting_id = a.id AND c.company_id = b.id
	);
END//
DELIMITER ;

-- Volcando estructura para procedimiento certificate_manager.sp_lock_company
DROP PROCEDURE IF EXISTS `sp_lock_company`;
DELIMITER //
CREATE PROCEDURE `sp_lock_company`()
BEGIN
	UPDATE company_membership AS a SET a.active = 0
	WHERE a.lock_date < CURDATE();
END//
DELIMITER ;

