-- Eliminando tabla temporal y crear estructura final de VIEW
DROP TABLE IF EXISTS `certificate_requests_months_view`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `certificate_requests_months_view` AS select concat(ucase(`b`.`company_name`),' NIT: ',`b`.`dni`) AS `company_name`,`a`.`life` AS `life`,count(`a`.`id`) AS `total`,`a`.`company_id` AS `company_id`,year(`a`.`updated_at`) AS `nyear`,month(`a`.`updated_at`) AS `nmonth`,monthname(`a`.`updated_at`) AS `monthname`,`a`.`request_status` AS `request_status` from (`certificate_requests` `a` join `companies` `b` on(`b`.`id` = `a`.`company_id`)) group by `a`.`company_id`,year(`a`.`updated_at`),month(`a`.`updated_at`),`a`.`request_status`,`a`.`life` order by `b`.`company_name`,year(`a`.`updated_at`),month(`a`.`updated_at`)
;

-- Eliminando tabla temporal y crear estructura final de VIEW
DROP TABLE IF EXISTS `certificate_requests_years_view`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `certificate_requests_years_view` AS select concat(ucase(`b`.`company_name`),' NIT: ',`b`.`dni`) AS `company_name`,`a`.`life` AS `life`,count(`a`.`id`) AS `total`,`a`.`company_id` AS `company_id`,year(`a`.`updated_at`) AS `nyear`,`a`.`request_status` AS `request_status` from (`certificate_requests` `a` join `companies` `b` on(`b`.`id` = `a`.`company_id`)) group by `a`.`company_id`,`a`.`request_status`,`a`.`life` order by `b`.`company_name`,year(`a`.`updated_at`) desc
;

